    85  static void view_vcf(htsFile *in) {
    86      if (!in) {
    87          return;
    88      }
    89      vcfFile *out = vcf_open("/dev/null", "w");
    90      if (!out) {
    91          abort();
    92      }
    93      bcf_hdr_t *hdr = bcf_hdr_read(in);
    94      if (hdr == NULL) {
    95          hts_close_or_abort(out);
    96          return;
    97      }
    98
    99      if (bcf_hdr_write(out, hdr) != 0) {
   100          bcf_hdr_destroy(hdr);
   101          hts_close_or_abort(out);
   102      }
   103      bcf1_t *rec = bcf_init();
   104      if (rec == NULL) {
   105          bcf_hdr_destroy(hdr);
   106          hts_close_or_abort(out);
   107      }
   108      while (bcf_read(in, hdr, rec) >= 0) {
   109          if (bcf_write(out, hdr, rec) < 0) {
   110              break;
   111          }
   112      }
   113      bcf_destroy(rec);
   114
   115      bcf_hdr_destroy(hdr);
   116      hts_close_or_abort(out);
